require __DIR__.'/includes/bootstrap.php';$id=(int)($_GET['id']??0);$st=db()->prepare("SELECT p.*,u.name seller_name,u.phone seller_phone FROM products p JOIN users u ON u.id=p.user_id WHERE p.id=?");$st->execute([$id]);$p=$st->fetch();if(!$p){http_response_code(404);exit('Listing not found');}$page_title=$p['title'];$me=current_user();
if($_SERVER['REQUEST_METHOD']==='POST'){require_login();verify_csrf();if($me['id']==$p['user_id']){flash('You cannot message yourself.');header('Location: '.url('product.php?id='.$id));exit;}$st=db()->prepare('SELECT id FROM conversations WHERE product_id=? AND buyer_id=? AND seller_id=?');$st->execute([$id,$me['id'],$p['user_id']]);$c=$st->fetch();if(!$c){$st=db()->prepare('INSERT INTO conversations(product_id,buyer_id,seller_id) VALUES(?,?,?)');$st->execute([$id,$me['id'],$p['user_id']]);$cid=db()->lastInsertId();}else{$cid=$c['id'];}header('Location: '.url('chat.php?id='.$cid));exit;}
include __DIR__.'/includes/header.php'; ?>
